import { useState } from 'react';

const Counter = () => {
  const [count, setCount] = useState(0);

  return (
    <div
      style={{ textAlign: 'center', fontFamily: 'sans-serif', padding: '24px' }}
    >
      <h2>Interactive Counter</h2>
      <h1
        style={{
          fontSize: '48px',
          margin: '16px 0',
          color: count >= 0 ? '#3182ce' : '#e53e3e',
        }}
      >
        {count}
      </h1>
      <div>
        <button
          style={{ padding: '8px 16px', margin: '0 4px', cursor: 'pointer' }}
          onClick={() => setCount(c => c - 1)}
        >
          -
        </button>
        <button
          style={{ padding: '8px 16px', margin: '0 4px', cursor: 'pointer' }}
          onClick={() => setCount(0)}
        >
          Reset
        </button>
        <button
          style={{ padding: '8px 16px', margin: '0 4px', cursor: 'pointer' }}
          onClick={() => setCount(c => c + 1)}
        >
          +
        </button>
      </div>
    </div>
  );
};

show(<Counter />);

